//! AWS Redis: ElastiCache for Valkey replication group, dedicated security group, cache subnet
//! group, parameter group, generated AUTH token secret, and the `redis/*` IAM policies.
//!
//! Mirrors the runtime Redis controller: same engine
//! version, TLS and AUTH always on, one node (or primary plus one replica with Multi-AZ),
//! snapshots only when `persistence` is on, 6379 admitted only from workload security groups.
//! The AUTH token is generated by Secrets Manager and read by ElastiCache through a
//! `{{resolve:secretsmanager:...}}` reference, so it never appears in the template.

use crate::emitters::aws::helpers::{
    cf_from_json, required_logical_id, resource_config, tags, uniquify_iam_statement_sids,
    vpc_id_expr,
};
use crate::{CfEmitter, CfExpression, CfResource};
use alien_core::{
    import::EmitContext, ComputeCluster, ErrorData, KubernetesCluster, KubernetesClusterProvider,
    Redis, ResourceLifecycle, Result,
};
use alien_error::{AlienError, Context, IntoAlienError};
use alien_permissions::{
    generators::AwsCloudFormationPermissionsGenerator, BindingTarget, PermissionContext,
};

use super::postgres::{
    first_security_group_id, named_private_subnet_ids_expr, permission_owners,
    resolve_secret_password, uses_default_network_statically, uses_dynamic_network_mode,
};

const REDIS_PORT: i64 = 6379;
/// Must equal `ENGINE_VERSION` / `PARAMETER_GROUP_FAMILY` / `SNAPSHOT_RETENTION_DAYS` in the
/// controller; a parity test against the runtime controller pins them.
pub const ENGINE_VERSION: &str = "9.0";
pub const PARAMETER_GROUP_FAMILY: &str = "valkey9";
pub const SNAPSHOT_RETENTION_DAYS: i64 = 7;
const CONDITION_NETWORK_MODE_HAS_NAMED_SUBNETS: &str = "NetworkModeHasNamedSubnets";

/// ElastiCache limit on replication group ids.
const MAX_REPLICATION_GROUP_ID_LEN: usize = 40;
/// Shortest resource prefix, hence the shortest stack name that can be deployed.
const MIN_STACK_NAME_LEN: usize = 3;

#[derive(Debug, Clone, Copy, Default)]
pub struct AwsRedisEmitter;

impl CfEmitter for AwsRedisEmitter {
    fn emit_resources(&self, ctx: &EmitContext<'_>) -> Result<Vec<CfResource>> {
        let redis = resource_config::<Redis>(ctx, Redis::RESOURCE_TYPE)?;
        let (node_type, _) = redis.elasticache_node_type()?;
        // The group id is `<stack name>-<id>` and ElastiCache caps it at 40 characters. The
        // stack name is chosen at deploy time, so the template can only refuse an id that fits
        // with no stack name of the shortest allowed length (3); a longer stack name is
        // refused by ElastiCache when the stack is created.
        if redis.id().len() + 1 + MIN_STACK_NAME_LEN > MAX_REPLICATION_GROUP_ID_LEN {
            return Err(AlienError::new(ErrorData::GenericError {
                message: format!(
                    "Redis id '{}' is too long for AWS: ElastiCache replication group ids are at most {MAX_REPLICATION_GROUP_ID_LEN} characters and are built as '<stack name>-<id>'. Use an id of at most {} characters",
                    redis.id(),
                    MAX_REPLICATION_GROUP_ID_LEN - 1 - MIN_STACK_NAME_LEN
                ),
            }));
        }
        let logical_id = required_logical_id(ctx)?;
        let key_arn = redis
            .encryption_key
            .as_ref()
            .map(|key| {
                ctx.name_for(key.id())
                    .map(|logical_id| CfExpression::get_att(logical_id, "Arn"))
                    .ok_or_else(|| {
                        AlienError::new(ErrorData::GenericError {
                            message: format!(
                                "missing encryption Key '{}' for Redis '{}'",
                                key.id(),
                                redis.id
                            ),
                        })
                    })
            })
            .transpose()?;

        let security_group_id = format!("{logical_id}SecurityGroup");
        let subnet_group_id = format!("{logical_id}SubnetGroup");
        let secret_id = format!("{logical_id}Secret");
        let parameter_group_id = format!("{logical_id}ParameterGroup");
        let group_id = format!("{logical_id}ReplicationGroup");

        let mut security_group = CfResource::new(
            security_group_id.clone(),
            "AWS::EC2::SecurityGroup".to_string(),
        );
        security_group.properties.insert(
            "GroupDescription".to_string(),
            CfExpression::from("ElastiCache Redis security group"),
        );
        security_group
            .properties
            .insert("VpcId".to_string(), vpc_id_expr(ctx));
        security_group
            .properties
            .insert("Tags".to_string(), tags(ctx));

        let mut ingress = CfResource::new(
            format!("{logical_id}SecurityGroupIngress"),
            "AWS::EC2::SecurityGroupIngress".to_string(),
        );
        ingress.properties.insert(
            "GroupId".to_string(),
            CfExpression::get_att(&security_group_id, "GroupId"),
        );
        ingress
            .properties
            .insert("IpProtocol".to_string(), CfExpression::from("tcp"));
        ingress
            .properties
            .insert("FromPort".to_string(), CfExpression::Integer(REDIS_PORT));
        ingress
            .properties
            .insert("ToPort".to_string(), CfExpression::Integer(REDIS_PORT));
        ingress.properties.insert(
            "SourceSecurityGroupId".to_string(),
            first_security_group_id(ctx),
        );
        ingress.properties.insert(
            "Description".to_string(),
            CfExpression::from("Allow stack workloads to reach Redis on 6379"),
        );
        // See the Postgres emitter: the optional SecurityGroupIds default trips W1035 on a
        // resource that is skipped for the default network.
        ingress.metadata.insert(
            "cfn-lint".to_string(),
            serde_json::json!({ "config": { "ignore_checks": ["W1035"] } }),
        );
        ingress.depends_on.push(security_group_id.clone());
        if uses_dynamic_network_mode(ctx) {
            ingress.condition = Some(CONDITION_NETWORK_MODE_HAS_NAMED_SUBNETS.to_string());
        }

        // Managed compute and EKS nodes have their own security groups.
        let mut compute_ingress = Vec::new();
        let eks_cluster = ctx.stack.resources().find_map(|(id, entry)| {
            let cluster = entry.config.downcast_ref::<KubernetesCluster>()?;
            (cluster.provider == KubernetesClusterProvider::Eks).then_some(id)
        });
        if let Some(id) = eks_cluster {
            let name = ctx.name_for(id).ok_or_else(|| {
                AlienError::new(ErrorData::GenericError {
                    message: format!("missing CloudFormation logical id for resource '{id}'"),
                })
            })?;
            let mut rule = ingress.clone();
            rule.metadata.shift_remove("cfn-lint");
            rule.logical_id = format!("{logical_id}IngressFrom{name}");
            rule.condition = None;
            rule.properties.insert(
                "SourceSecurityGroupId".to_string(),
                CfExpression::get_att(format!("{name}Cluster"), "ClusterSecurityGroupId"),
            );
            compute_ingress.push(rule);
        }
        for (id, entry) in ctx.stack.resources() {
            if eks_cluster.is_some()
                || entry.lifecycle != ResourceLifecycle::Frozen
                || entry.config.downcast_ref::<ComputeCluster>().is_none()
            {
                continue;
            }
            let name = ctx.name_for(id).ok_or_else(|| {
                AlienError::new(ErrorData::GenericError {
                    message: format!("missing CloudFormation logical id for resource '{id}'"),
                })
            })?;
            let mut rule = ingress.clone();
            rule.metadata.shift_remove("cfn-lint");
            rule.logical_id = format!("{logical_id}IngressFrom{name}");
            rule.condition = None;
            rule.properties.insert(
                "SourceSecurityGroupId".to_string(),
                CfExpression::get_att(format!("{name}SecurityGroup"), "GroupId"),
            );
            compute_ingress.push(rule);
        }

        let mut subnet_group = CfResource::new(
            subnet_group_id.clone(),
            "AWS::ElastiCache::SubnetGroup".to_string(),
        );
        subnet_group.properties.insert(
            "Description".to_string(),
            CfExpression::from(format!("Subnet group for Redis '{}'", redis.id())),
        );
        subnet_group
            .properties
            .insert("SubnetIds".to_string(), named_private_subnet_ids_expr(ctx));
        subnet_group
            .properties
            .insert("Tags".to_string(), tags(ctx));
        if uses_dynamic_network_mode(ctx) {
            subnet_group.condition = Some(CONDITION_NETWORK_MODE_HAS_NAMED_SUBNETS.to_string());
        }

        // 64 hex characters: inside ElastiCache's 16-128 character limit and free of the
        // characters it rejects (`@`, `"`, `/`).
        let mut secret =
            CfResource::new(secret_id.clone(), "AWS::SecretsManager::Secret".to_string());
        secret.properties.insert(
            "Name".to_string(),
            CfExpression::sub(format!("${{AWS::StackName}}-{}-auth", redis.id())),
        );
        secret.properties.insert(
            "Description".to_string(),
            CfExpression::from(format!("Redis AUTH token for '{}'", redis.id())),
        );
        secret.properties.insert(
            "GenerateSecretString".to_string(),
            CfExpression::object([
                ("PasswordLength", CfExpression::Integer(64)),
                ("ExcludePunctuation", CfExpression::from(true)),
                ("ExcludeUppercase", CfExpression::from(true)),
                (
                    "ExcludeCharacters",
                    CfExpression::from("ghijklmnopqrstuvwxyz"),
                ),
            ]),
        );
        secret.properties.insert("Tags".to_string(), tags(ctx));
        secret.deletion_policy = Some("Delete".to_string());
        secret.update_replace_policy = Some("Delete".to_string());

        let mut parameter_group = CfResource::new(
            parameter_group_id.clone(),
            "AWS::ElastiCache::ParameterGroup".to_string(),
        );
        parameter_group.properties.insert(
            "Description".to_string(),
            CfExpression::from(format!("Valkey settings for Redis '{}'", redis.id())),
        );
        parameter_group.properties.insert(
            "CacheParameterGroupFamily".to_string(),
            CfExpression::from(PARAMETER_GROUP_FAMILY),
        );
        parameter_group.properties.insert(
            "Properties".to_string(),
            CfExpression::object([(
                "maxmemory-policy",
                CfExpression::from(redis.eviction_policy.as_str()),
            )]),
        );
        parameter_group
            .properties
            .insert("Tags".to_string(), tags(ctx));

        let mut group = CfResource::new(
            group_id.clone(),
            "AWS::ElastiCache::ReplicationGroup".to_string(),
        );
        let properties = [
            (
                "ReplicationGroupId",
                CfExpression::sub(format!("${{AWS::StackName}}-{}", redis.id())),
            ),
            (
                "ReplicationGroupDescription",
                CfExpression::from(format!("Alien Redis '{}'", redis.id())),
            ),
            ("Engine", CfExpression::from("valkey")),
            ("EngineVersion", CfExpression::from(ENGINE_VERSION)),
            ("CacheNodeType", CfExpression::from(node_type)),
            (
                "NumCacheClusters",
                CfExpression::Integer(if redis.high_availability { 2 } else { 1 }),
            ),
            (
                "AutomaticFailoverEnabled",
                CfExpression::from(redis.high_availability),
            ),
            ("MultiAZEnabled", CfExpression::from(redis.high_availability)),
            (
                "CacheParameterGroupName",
                CfExpression::ref_(&parameter_group_id),
            ),
            (
                "SecurityGroupIds",
                CfExpression::list([CfExpression::get_att(&security_group_id, "GroupId")]),
            ),
            ("TransitEncryptionEnabled", CfExpression::from(true)),
            ("TransitEncryptionMode", CfExpression::from("required")),
            ("AtRestEncryptionEnabled", CfExpression::from(true)),
            ("AuthToken", resolve_secret_password(&secret_id)),
            (
                "SnapshotRetentionLimit",
                CfExpression::Integer(if redis.persistence {
                    SNAPSHOT_RETENTION_DAYS
                } else {
                    0
                }),
            ),
            ("Tags", tags(ctx)),
        ];
        for (key, value) in properties {
            group.properties.insert(key.to_string(), value);
        }
        if let Some(key_arn) = key_arn {
            group.properties.insert("KmsKeyId".to_string(), key_arn);
        }
        // In use-default mode ElastiCache uses the default VPC's default subnet group.
        if uses_dynamic_network_mode(ctx) {
            group.properties.insert(
                "CacheSubnetGroupName".to_string(),
                CfExpression::if_(
                    CONDITION_NETWORK_MODE_HAS_NAMED_SUBNETS,
                    CfExpression::ref_(&subnet_group_id),
                    CfExpression::no_value(),
                ),
            );
        } else if !uses_default_network_statically(ctx) {
            group.properties.insert(
                "CacheSubnetGroupName".to_string(),
                CfExpression::ref_(&subnet_group_id),
            );
        }
        group.depends_on.push(secret_id.clone());
        group.depends_on.push(security_group_id.clone());
        // A delete removes the data, as the controller does.
        group.deletion_policy = Some("Delete".to_string());
        group.update_replace_policy = Some("Delete".to_string());

        let mut resources = vec![security_group];
        if !uses_default_network_statically(ctx) {
            resources.push(ingress);
            resources.push(subnet_group);
        }
        resources.extend([secret, parameter_group, group]);
        resources.extend(compute_ingress);
        resources.extend(redis_iam_policies(ctx, redis, &secret_id, &parameter_group_id)?);
        Ok(resources)
    }

    fn emit_import_ref(&self, ctx: &EmitContext<'_>) -> Result<CfExpression> {
        let redis = resource_config::<Redis>(ctx, Redis::RESOURCE_TYPE)?;
        let (node_type, _) = redis.elasticache_node_type()?;
        let logical_id = required_logical_id(ctx)?;
        let group_id = format!("{logical_id}ReplicationGroup");
        Ok(CfExpression::object([
            ("replicationGroupId", CfExpression::ref_(&group_id)),
            (
                "subnetGroupName",
                if uses_default_network_statically(ctx) {
                    CfExpression::from("default")
                } else if uses_dynamic_network_mode(ctx) {
                    CfExpression::if_(
                        CONDITION_NETWORK_MODE_HAS_NAMED_SUBNETS,
                        CfExpression::ref_(format!("{logical_id}SubnetGroup")),
                        CfExpression::from("default"),
                    )
                } else {
                    CfExpression::ref_(format!("{logical_id}SubnetGroup"))
                },
            ),
            (
                "securityGroupId",
                CfExpression::get_att(format!("{logical_id}SecurityGroup"), "GroupId"),
            ),
            (
                "parameterGroupName",
                CfExpression::ref_(format!("{logical_id}ParameterGroup")),
            ),
            (
                "authSecretArn",
                CfExpression::ref_(format!("{logical_id}Secret")),
            ),
            (
                "endpoint",
                CfExpression::get_att(&group_id, "PrimaryEndPoint.Address"),
            ),
            ("port", CfExpression::Integer(REDIS_PORT)),
            ("nodeType", CfExpression::from(node_type)),
            ("engineVersion", CfExpression::from(ENGINE_VERSION)),
            (
                "highAvailability",
                CfExpression::from(redis.high_availability),
            ),
        ]))
    }

    fn emit_binding_ref(&self, ctx: &EmitContext<'_>) -> Result<Option<CfExpression>> {
        let logical_id = required_logical_id(ctx)?;
        Ok(Some(CfExpression::object([
            ("service", CfExpression::from("elasticache")),
            (
                "host",
                CfExpression::get_att(
                    format!("{logical_id}ReplicationGroup"),
                    "PrimaryEndPoint.Address",
                ),
            ),
            ("port", CfExpression::Integer(REDIS_PORT)),
            ("username", CfExpression::from("default")),
            (
                "passwordSecretArn",
                CfExpression::ref_(format!("{logical_id}Secret")),
            ),
        ])))
    }
}

/// `redis/management` declares no AWS block: management reads Redis state through the
/// `redis/heartbeat` grants and never touches the password. Only a set with no AWS block at all
/// is skipped; a set that has one and fails to render still fails the template.
fn has_no_aws_block(permission_set: &alien_core::PermissionSet) -> bool {
    permission_set.platforms.aws.is_none()
}

/// Inline `AWS::IAM::Policy` resources for the stack's `redis/*` permission sets (chiefly
/// `redis/data-access`: read the AUTH secret). Management and access only, never ownership.
fn redis_iam_policies(
    ctx: &EmitContext<'_>,
    redis: &Redis,
    secret_id: &str,
    parameter_group_id: &str,
) -> Result<Vec<CfResource>> {
    let mut resources = Vec::new();
    let generator = AwsCloudFormationPermissionsGenerator::new();
    // The bare resource id, so `${stackPrefix}-${resourceName}-*` matches the `{id}-auth` secret.
    let context = PermissionContext::new()
        .with_stack_prefix("")
        .with_aws_region("${AWS::Region}")
        .with_aws_account_id("${AWS::AccountId}")
        .with_managing_role_arn("${ManagingRoleArn}")
        .with_resource_name(redis.id().to_string());
    let policy_scope = required_logical_id(ctx)?;

    for (owner_index, (role_id, permission_refs)) in permission_owners(ctx, "redis/") {
        for (permission_index, permission_ref) in permission_refs.iter().enumerate() {
            let Some(permission_set) =
                permission_ref.resolve(|name| alien_permissions::get_permission_set(name).cloned())
            else {
                continue;
            };
            if !permission_set.id.starts_with("redis/") || permission_set.id.ends_with("/provision")
            {
                continue;
            }
            if has_no_aws_block(&permission_set) {
                continue;
            }
            let policy = generator
                .generate_policy(&permission_set, BindingTarget::Resource, &context)
                .context(ErrorData::OperationNotSupported {
                    operation: "generate AWS CloudFormation Redis IAM policy".to_string(),
                    reason: format!(
                        "failed to generate IAM policy for permission set '{}'",
                        permission_set.id
                    ),
                })?;
            if policy.statement.is_empty() {
                continue;
            }
            let policy_value = serde_json::to_value(policy).into_alien_error().context(
                ErrorData::TemplateSerializationFailed {
                    format: "CloudFormation IAM policy".to_string(),
                    reason: "Failed to serialize redis IAM policy".to_string(),
                },
            )?;
            let CfExpression::Object(mut policy_object) = cf_from_json(policy_value)? else {
                return Err(AlienError::new(ErrorData::TemplateSerializationFailed {
                    format: "CloudFormation IAM policy".to_string(),
                    reason: "policy did not serialize to a JSON object".to_string(),
                }));
            };
            let Some(CfExpression::List(statements)) = policy_object.shift_remove("Statement")
            else {
                return Err(AlienError::new(ErrorData::TemplateSerializationFailed {
                    format: "CloudFormation IAM policy".to_string(),
                    reason: "policy serialized without a `Statement` list".to_string(),
                }));
            };
            let mut statements = statements;
            if permission_set.id == "redis/heartbeat" {
                // CloudFormation names the parameter group itself (`custom-cache-<random>`), so
                // the name pattern in the permission set cannot match it. Grant the one read
                // heartbeat needs on exactly this group.
                statements.push(CfExpression::object([
                    ("Sid", CfExpression::from("ReadGeneratedParameterGroup")),
                    ("Effect", CfExpression::from("Allow")),
                    (
                        "Action",
                        CfExpression::list([CfExpression::from(
                            "elasticache:DescribeCacheParameters",
                        )]),
                    ),
                    (
                        "Resource",
                        CfExpression::sub(format!(
                            "arn:${{AWS::Partition}}:elasticache:${{AWS::Region}}:${{AWS::AccountId}}:parametergroup:${{{parameter_group_id}}}"
                        )),
                    ),
                ]));
            }
            let mut policy_resource = CfResource::new(
                format!("{role_id}Redis{policy_scope}Permission{owner_index}{permission_index}"),
                "AWS::IAM::Policy".to_string(),
            );
            policy_resource.properties.insert(
                "PolicyName".to_string(),
                CfExpression::sub(format!(
                    "${{AWS::StackName}}-{}-redis-{owner_index}-{permission_index}",
                    redis.id()
                )),
            );
            policy_resource.properties.insert(
                "PolicyDocument".to_string(),
                CfExpression::object([
                    ("Version", CfExpression::from("2012-10-17")),
                    (
                        "Statement",
                        CfExpression::list(uniquify_iam_statement_sids(statements)),
                    ),
                ]),
            );
            policy_resource.properties.insert(
                "Roles".to_string(),
                CfExpression::list([CfExpression::ref_(&role_id)]),
            );
            policy_resource.depends_on.push(secret_id.to_string());
            policy_resource.depends_on.push(role_id.clone());
            resources.push(policy_resource);
        }
    }
    Ok(resources)
}

#[cfg(test)]
mod tests {
    use super::has_no_aws_block;

    #[test]
    fn only_a_set_without_an_aws_block_is_skipped() {
        let get = |id: &str| alien_permissions::get_permission_set(id).unwrap().clone();
        assert!(has_no_aws_block(&get("redis/management")));
        for id in ["redis/heartbeat", "redis/data-access", "redis/setup"] {
            assert!(!has_no_aws_block(&get(id)), "{id} has AWS grants");
        }
        // An empty AWS block is still a block: it must reach the generator.
        let mut empty = get("redis/management");
        empty.platforms.aws = Some(Vec::new());
        assert!(!has_no_aws_block(&empty));
    }
}
